import java.util.*; public class DutyRosterRotation { static String[] rotateRoster(String[] names,long k){String[] result=new String[names.length];int shift=(int)(k%names.length);for(int i=0;i<names.length;i++)result[(i+shift)%names.length]=names[i];return result;} public static void main(String[]args){System.out.println(Arrays.toString(rotateRoster(new String[]{"A","B","C","D","E"},2)));} }
